import { render, screen, fireEvent } from '@testing-library/react';
import App from './UserCode';

test('Coming Soon button is disabled', () => {
  render(<App />);
  const btn = screen.getByText('Coming Soon');
  expect(btn.disabled).toBe(true);
});

test('Show Message button is enabled and calls alert on click', () => {
  render(<App />);
  const btn = screen.getByText('Show Message');
  expect(btn.disabled).toBe(false);

  // Giả lập hàm window.alert để bắt xem học viên có gọi đúng không
  window.alert = jest.fn();
  fireEvent.click(btn);
  expect(window.alert).toHaveBeenCalledWith('Hello React!');
});

