import StatusBadge from './UserCode';

test('renders Online with correct class when isOnline is true', () => {
  render(<StatusBadge isOnline={true} />);
  const badge = screen.getByText('Online');
  expect(badge).toBeTruthy();
  expect(badge.className).toContain('badge-online');
});

test('renders Offline with correct class when isOnline is false', () => {
  render(<StatusBadge isOnline={false} />);
  const badge = screen.getByText('Offline');
  expect(badge).toBeTruthy();
  expect(badge.className).toContain('badge-offline');
});

import { render, screen } from '@testing-library/react';
import * as UserCode from './UserCode';

// Tìm component Product (bảo vệ trường hợp học viên export named hoặc default)
const Product = UserCode.Product || UserCode.default;

test('renders product with provided category', () => {
  if (!Product) throw new Error("Cannot find Product component. Did you export it?");
  render(<Product name="Laptop" price="1000" category="Electronics" />);
  expect(screen.getByText('Laptop')).toBeTruthy();
  expect(screen.getByText('1000')).toBeTruthy();
  expect(screen.getByText('Electronics')).toBeTruthy();
});

test('renders product with default category', () => {
  if (!Product) throw new Error("Cannot find Product component. Did you export it?");
  render(<Product name="Book" price="20" />);
  expect(screen.getByText('Book')).toBeTruthy();
  expect(screen.getByText('20')).toBeTruthy();
  expect(screen.getByText('General')).toBeTruthy();
});

